create index if not exists idx_planner_post_name_category_id on public.post_name(category,post_id);
create index if not exists idx_planner_post_arxiv_name_post on public.post_arxiv(name_post);
-- Existing imports sometimes used explicit staff IDs. Align the sequence once as
-- migration owner; runtime callers need only their existing USAGE privilege.
do $$
declare sequence_name text; max_id bigint; current_value bigint;
begin
 lock table public.slyusars in share row exclusive mode;
 sequence_name:=pg_get_serial_sequence('public.slyusars','slyusar_id');
 if sequence_name is not null then
  select max(slyusar_id) into max_id from public.slyusars;
  execute format('select last_value from %s',sequence_name::regclass) into current_value;
  if max_id is not null and current_value<=max_id then perform setval(sequence_name::regclass,max_id,true);end if;
 end if;
end $$;

create or replace function public.traffic_planner_name(p_value text)
returns text language sql immutable security invoker set search_path=pg_catalog,public as $$
 select lower(regexp_replace(btrim(coalesce(p_value,'')), '[[:space:]]+', ' ', 'g'))
$$;
create or replace function public.traffic_planner_staff_document(p_value jsonb)
returns jsonb language plpgsql immutable security invoker set search_path=pg_catalog,public as $$
declare v jsonb:=p_value;
begin
 if jsonb_typeof(v)='string' then
  begin v:=(v#>>'{}')::jsonb; exception when invalid_text_representation then return '{}'::jsonb;end;
 end if;
 return case when jsonb_typeof(v)='object' then v else '{}'::jsonb end;
end $$;

create or replace function public.traffic_planner_post_options(
 p_kind text,p_category_id bigint default null,p_query text default '',p_after bigint default null,p_limit integer default 30)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb; q text:=public.traffic_planner_name(p_query); page_limit integer:=least(greatest(coalesce(p_limit,30),1),50);
begin
 if p_kind not in ('category','post','staff') or p_kind is null then raise exception 'Невідомий довідник планувальника';end if;
 if length(coalesce(p_query,''))>200 or coalesce(p_after,0)<0 then raise exception 'Некоректні параметри пошуку';end if;
 if p_kind='post' and coalesce(p_category_id,0)<=0 then raise exception 'Спочатку виберіть цех';end if;
 if p_kind='category' then
  with candidates as materialized (
   select category_id::bigint id,category name from public.post_category
   where category_id>coalesce(p_after,0) and strpos(public.traffic_planner_name(category),q)>0
   order by category_id limit page_limit+1
  ), page as (select * from candidates order by id limit page_limit)
  select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(page) order by id) from page),'[]'::jsonb),
   'has_more',(select count(*)>page_limit from candidates),
   'next_cursor',case when (select count(*)>page_limit from candidates) then (select max(id) from page) else null end) into result;
 elsif p_kind='post' then
  with candidates as materialized (
   select post_id::bigint id,name,category from public.post_name
   where category=p_category_id and post_id>coalesce(p_after,0) and strpos(public.traffic_planner_name(name),q)>0
   order by post_id limit page_limit+1
  ), page as (select * from candidates order by id limit page_limit)
  select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(page) order by id) from page),'[]'::jsonb),
   'has_more',(select count(*)>page_limit from candidates),
   'next_cursor',case when (select count(*)>page_limit from candidates) then (select max(id) from page) else null end) into result;
 else
  with candidates as materialized (
   select slyusar_id::bigint id,public.traffic_planner_staff_document(to_jsonb(data))->>'Name' name from public.slyusars
   where slyusar_id>coalesce(p_after,0)
    and nullif(btrim(public.traffic_planner_staff_document(to_jsonb(data))->>'Name'),'') is not null
    and strpos(public.traffic_planner_name(public.traffic_planner_staff_document(to_jsonb(data))->>'Name'),q)>0
   order by slyusar_id limit page_limit+1
  ), page as (select * from candidates order by id limit page_limit)
  select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(page) order by id) from page),'[]'::jsonb),
   'has_more',(select count(*)>page_limit from candidates),
   'next_cursor',case when (select count(*)>page_limit from candidates) then (select max(id) from page) else null end) into result;
 end if;
 return result;
end $$;

create or replace function public.traffic_planner_directory_write(
 p_action text,p_category_id bigint default null,p_post_id bigint default null,
 p_patch jsonb default '{}'::jsonb,p_expected jsonb default '{}'::jsonb)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare c jsonb; p jsonb; ids bigint[]; n text; k text; affected bigint; status text:='unchanged';
 category_changed boolean:=false; post_changed boolean:=false; target_category bigint;
begin
 if p_action is null or p_action not in ('add','edit','delete') or jsonb_typeof(p_patch) is distinct from 'object'
  or jsonb_typeof(p_expected) is distinct from 'object' or coalesce(p_category_id,1)<=0 or coalesce(p_post_id,1)<=0 then raise exception 'Некоректна операція планувальника';end if;
 if exists(select 1 from jsonb_object_keys(p_patch) as fields(key) where fields.key not in ('category','name')) then raise exception 'Дозволені лише назви цеху та поста';end if;
 for k in select jsonb_object_keys(p_patch) loop
  if jsonb_typeof(p_patch->k) is distinct from 'string' or length(btrim(p_patch->>k)) not between 1 and 200 then raise exception 'Назва має містити від 1 до 200 символів';end if;
 end loop;
 -- The same lock order is used by assignment. Legacy direct inserts cannot race MAX+1.
 lock table public.post_category,public.post_name,public.slyusars in share row exclusive mode;
 if p_action='add' then
  if p_post_id is not null then raise exception 'Для додавання не передавайте ID існуючого поста';end if;
  if p_category_id is not null then
   select jsonb_build_object('category_id',category_id,'category',category) into c from public.post_category where category_id=p_category_id for update;
   if c is null then raise exception 'Цех не знайдено або немає доступу';end if;
   if p_patch?'category' and public.traffic_planner_name(c->>'category')<>public.traffic_planner_name(p_patch->>'category') then raise exception 'Вибраний цех змінився. Виберіть його повторно';end if;
  else
   if not(p_patch?'category') then raise exception 'Виберіть або введіть цех';end if;
   n:=btrim(p_patch->>'category');
   select array_agg(category_id order by category_id) into ids from public.post_category where public.traffic_planner_name(category)=public.traffic_planner_name(n);
   if coalesce(cardinality(ids),0)>1 then raise exception 'Неоднозначна назва цеху. Виберіть конкретний ID';end if;
   p_category_id:=ids[1];
   if p_category_id is null then
    select coalesce(max(category_id),0)+1 into p_category_id from public.post_category;
    insert into public.post_category(category_id,category) values(p_category_id,n);get diagnostics affected=row_count;
    if affected<>1 then raise exception 'База не підтвердила створення цеху';end if;
    status:='created';
   end if;
   select jsonb_build_object('category_id',category_id,'category',category) into c from public.post_category where category_id=p_category_id;
  end if;
  if p_patch?'name' then
   n:=btrim(p_patch->>'name');
   select array_agg(post_id order by post_id) into ids from public.post_name where category=p_category_id and public.traffic_planner_name(name)=public.traffic_planner_name(n);
   if coalesce(cardinality(ids),0)>1 then raise exception 'Неоднозначна назва поста. Виберіть конкретний ID';end if;
   p_post_id:=ids[1];
   if p_post_id is null then
    select coalesce(max(post_id),0)+1 into p_post_id from public.post_name;
    insert into public.post_name(post_id,name,category) values(p_post_id,n,p_category_id);get diagnostics affected=row_count;
    if affected<>1 then raise exception 'База не підтвердила створення поста';end if;
    status:='created';
   end if;
   select jsonb_build_object('post_id',post_id,'name',name,'category',category) into p from public.post_name where post_id=p_post_id;
  end if;
 else
  if p_post_id is not null then
   select jsonb_build_object('post_id',post_id,'name',name,'category',category) into p from public.post_name where post_id=p_post_id for update;
   if p is null then raise exception 'Пост не знайдено або немає доступу';end if;
   target_category:=(p->>'category')::bigint;
   if p_category_id is distinct from target_category then raise exception 'Пост належить іншому цеху. Виберіть його повторно';end if;
   if not(p_expected?'post_category') or (p_expected->>'post_category')::bigint is distinct from target_category then raise exception 'Прив’язка поста змінилася. Оновіть вибір';end if;
  end if;
  if p_category_id is null then raise exception 'Спочатку виберіть конкретний цех або пост';end if;
  select jsonb_build_object('category_id',category_id,'category',category) into c from public.post_category where category_id=p_category_id for update;
  if c is null then raise exception 'Цех не знайдено або немає доступу';end if;
  if p_action='delete' then
   if p_post_id is not null then
    if not(p_expected?'name') or p->'name' is distinct from p_expected->'name' then raise exception 'Назва поста змінилася. Оновіть вибір';end if;
    lock table public.post_arxiv in share row exclusive mode;
    if exists(select 1 from public.slyusars where case when btrim(post_sluysar) ~ '^[+]?[0-9]+([.]0+)?$' then btrim(post_sluysar)::numeric=p_post_id else false end)
     or exists(select 1 from public.post_arxiv where name_post=p_post_id::double precision) then raise exception 'Пост використовується працівником або має історію записів. Видалення заблоковано';end if;
    delete from public.post_name where post_id=p_post_id;get diagnostics affected=row_count;
   else
    if not(p_expected?'category') or c->'category' is distinct from p_expected->'category' then raise exception 'Назва цеху змінилася. Оновіть вибір';end if;
    if exists(select 1 from public.post_name where category=p_category_id) then raise exception 'Цех містить пости. Видалення заблоковано';end if;
    delete from public.post_category where category_id=p_category_id;get diagnostics affected=row_count;
   end if;
   if affected<>1 then raise exception 'База не підтвердила видалення. Перевірте доступ' using errcode='42501';end if;
   status:='deleted';
  else
   if p_patch?'name' and p_post_id is null then raise exception 'Для редагування виберіть конкретний пост зі списку';end if;
   if p_patch?'category' then
    if not(p_expected?'category') then raise exception 'Відсутня початкова назва цеху';end if;
    n:=btrim(p_patch->>'category');
    if c->'category' is distinct from p_expected->'category' and c->>'category' is distinct from n then raise exception 'Назву цеху змінено іншим користувачем';end if;
    category_changed:=c->>'category' is distinct from n;
    if category_changed then
     if exists(select 1 from public.post_category where category_id<>p_category_id and public.traffic_planner_name(category)=public.traffic_planner_name(n)) then raise exception 'Цех із такою назвою вже існує';end if;
     update public.post_category set category=n where category_id=p_category_id;get diagnostics affected=row_count;
     if affected<>1 then raise exception 'База не підтвердила редагування цеху' using errcode='42501';end if;
     c:=jsonb_set(c,'{category}',to_jsonb(n));
    end if;
   end if;
   if p_patch?'name' then
    if not(p_expected?'name') then raise exception 'Відсутня початкова назва поста';end if;
    n:=btrim(p_patch->>'name');
    if p->'name' is distinct from p_expected->'name' and p->>'name' is distinct from n then raise exception 'Назву поста змінено іншим користувачем';end if;
    post_changed:=p->>'name' is distinct from n;
    if post_changed then
     if exists(select 1 from public.post_name where post_id<>p_post_id and category=p_category_id and public.traffic_planner_name(name)=public.traffic_planner_name(n)) then raise exception 'Пост із такою назвою вже існує в цьому цеху';end if;
     update public.post_name set name=n where post_id=p_post_id;get diagnostics affected=row_count;
     if affected<>1 then raise exception 'База не підтвердила редагування поста' using errcode='42501';end if;
     p:=jsonb_set(p,'{name}',to_jsonb(n));
    end if;
   end if;
   if category_changed or post_changed then status:='updated';end if;
  end if;
 end if;
 if c is null or (p_post_id is not null and p is null) then raise exception 'База не повернула збережені дані. Перевірте доступ';end if;
 return jsonb_build_object('status',status,'category',c,'post',p);
end $$;

create or replace function public.traffic_planner_post_assign(
 p_category text,p_post text,p_staff_name text,p_staff_id bigint default null,p_namber double precision default null,
 p_category_id bigint default null,p_post_id bigint default null)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare receipt jsonb; c jsonb; p jsonb; s jsonb; ids bigint[]; staff_id bigint; affected bigint; value_type text; staff_sequence text; max_staff_id bigint; sequence_steps integer:=0;
 old_post text; old_number double precision; actual_name text; status text:='updated';
begin
 p_category:=btrim(p_category);p_post:=btrim(p_post);p_staff_name:=btrim(p_staff_name);
 if coalesce(length(p_category),0) not between 1 and 200 or coalesce(length(p_post),0) not between 1 and 200
  or coalesce(length(p_staff_name),0) not between 1 and 200 or coalesce(p_staff_id,1)<=0
  or coalesce(p_category_id,1)<=0 or coalesce(p_post_id,1)<=0
  or p_namber is null or p_namber<=0 or p_namber::text in ('NaN','Infinity','-Infinity') then raise exception 'Заповніть цех, пост, слюсаря та порядок рядка';end if;
 lock table public.post_category,public.post_name,public.slyusars in share row exclusive mode;
 if p_staff_id is null then
  select array_agg(slyusar_id order by slyusar_id) into ids from public.slyusars
   where public.traffic_planner_name(public.traffic_planner_staff_document(to_jsonb(data))->>'Name')=public.traffic_planner_name(p_staff_name);
  if coalesce(cardinality(ids),0)>1 then raise exception 'Неоднозначне ПІБ. Виберіть конкретного слюсаря зі списку';end if;
  staff_id:=ids[1];
 else staff_id:=p_staff_id;end if;
 if staff_id is not null then
  select public.traffic_planner_staff_document(to_jsonb(data))->>'Name',post_sluysar,namber
   into actual_name,old_post,old_number from public.slyusars where slyusar_id=staff_id for update;
  if not found then raise exception 'Слюсаря не знайдено або немає доступу';end if;
  if public.traffic_planner_name(actual_name)<>public.traffic_planner_name(p_staff_name) then raise exception 'ПІБ вибраного слюсаря змінилося. Оновіть вибір';end if;
 else actual_name:=p_staff_name;end if;
 if p_post_id is not null then
  select jsonb_build_object('post_id',post_id,'name',name,'category',category) into p from public.post_name where post_id=p_post_id for update;
  if p is null then raise exception 'Вибраний пост не знайдено або немає доступу';end if;
  if p_category_id is null then p_category_id:=(p->>'category')::bigint;end if;
  if (p->>'category')::bigint<>p_category_id or public.traffic_planner_name(p->>'name')<>public.traffic_planner_name(p_post) then raise exception 'Вибраний пост змінився. Виберіть його повторно';end if;
  select jsonb_build_object('category_id',category_id,'category',category) into c from public.post_category where category_id=p_category_id for update;
  if c is null or public.traffic_planner_name(c->>'category')<>public.traffic_planner_name(p_category) then raise exception 'Вибраний цех змінився. Виберіть його повторно';end if;
 else
  receipt:=public.traffic_planner_directory_write('add',p_category_id,null,jsonb_build_object('category',p_category,'name',p_post),'{}');
  c:=receipt->'category';p:=receipt->'post';
 end if;
 if staff_id is not null then
  if old_number is not null and nullif(btrim(old_post),'') is not null then
   if (case when btrim(old_post) ~ '^[+]?[0-9]+([.]0+)?$' then btrim(old_post)::numeric=(p->>'post_id')::bigint else false end) then status:='unchanged';
   else raise exception 'Слюсар уже доданий до іншого поста планувальника';end if;
  else
   update public.slyusars set namber=p_namber,post_sluysar=p->>'post_id' where slyusar_id=staff_id;get diagnostics affected=row_count;
   if affected<>1 then raise exception 'База не підтвердила призначення слюсаря' using errcode='42501';end if;
   old_number:=p_namber;old_post:=p->>'post_id';
  end if;
 else
  select coalesce(max(slyusar_id),0) into max_staff_id from public.slyusars;
  staff_sequence:=pg_get_serial_sequence('public.slyusars','slyusar_id');
  if staff_sequence is null then staff_id:=max_staff_id+1;
  else
   loop
    staff_id:=nextval(staff_sequence::regclass);sequence_steps:=sequence_steps+1;
    exit when staff_id>max_staff_id;
    if sequence_steps>=1000 then raise exception 'Лічильник ID слюсарів відстає після імпорту. Повторно виконайте SQL-пакет planner-post-modal-repair.sql';end if;
   end loop;
  end if;
  select format_type(a.atttypid,a.atttypmod) into value_type from pg_attribute a where a.attrelid='public.slyusars'::regclass and a.attname='data';
  execute format('insert into public.slyusars(slyusar_id,data,namber,post_sluysar) values($1,$2::%s,$3,$4)',value_type)
   using staff_id,jsonb_build_object('Name',actual_name,'Опис','{}'::jsonb,'Доступ','Слюсар')::text,p_namber,p->>'post_id';
  get diagnostics affected=row_count;
  if affected<>1 then raise exception 'База не підтвердила створення слюсаря' using errcode='42501';end if;
  old_number:=p_namber;old_post:=p->>'post_id';status:='created';
 end if;
 s:=jsonb_build_object('slyusar_id',staff_id,'name',actual_name,'namber',old_number,'post_sluysar',old_post);
 return jsonb_build_object('status',status,'category',c,'post',p,'staff',s);
end $$;

